{% set plan = states.sensor.hoymiles_hit_rcm_voltage_plan %}
{% set plan_current = plan is not none
   and plan.attributes.result_current is sameas true
   and plan.attributes.recalculation_pending is sameas false %}
{% if plan_current %}
{% set status_code = plan.attributes.status_code | default('missing_data', true) %}
{% set action = plan.attributes.action | default('none', true) %}
{% set horizon = plan.attributes.risk_surplus_horizon | default('missing', true) %}
{% set l1 = plan.attributes.voltage_l1_v | default(none, true) %}
{% set l2 = plan.attributes.voltage_l2_v | default(none, true) %}
{% set l3 = plan.attributes.voltage_l3_v | default(none, true) %}
{% set maximum = plan.attributes.maximum_voltage_v | default(none, true) %}
{% set maximum_phase = 'L1' if l1 is number and maximum is number and l1 == maximum else 'L2' if l2 is number and maximum is number and l2 == maximum else 'L3' if l3 is number and maximum is number and l3 == maximum else 'Brak danych' %}
{% set status_labels = {'ready': 'Sieć w bezpiecznym zakresie', 'learning': 'Uczenie historii napięcia', 'preparing_headroom': 'Przewidywane ryzyko — zachowanie miejsca', 'preparing_discharge': 'Przewidywane ryzyko — przygotowanie miejsca', 'controlling': 'Podwyższone napięcie — aktywna regulacja', 'battery_limited': 'Podwyższone napięcie — magazyn ograniczony', 'emergency': 'Próg 253 V osiągnięty', 'emergency_actuator_unavailable': 'Próg 253 V bez świeżych aktuatorów', 'battery_charge_unavailable': 'Podwyższone napięcie — BMS nie przyjmuje energii', 'stale_voltage': 'Stan sieci nieznany — napięcia nieaktualne', 'history_stale': 'Bieżąca sieć dostępna, predykcja wstrzymana', 'forecast_stale': 'Bieżąca sieć dostępna, prognoza nieaktualna', 'missing_data': 'Stan sieci nieznany — brak danych', 'optimizer_error': 'Stan sieci nieznany — błąd obliczeń'} %}
{% set risk_labels = {'ready': 'Niskie', 'learning': 'Brak oceny predykcyjnej', 'preparing_headroom': 'Przewidywane', 'preparing_discharge': 'Przewidywane', 'controlling': 'Wysokie', 'battery_limited': 'Wysokie', 'emergency': 'Krytyczne', 'emergency_actuator_unavailable': 'Krytyczne', 'battery_charge_unavailable': 'Wysokie', 'stale_voltage': 'Brak danych', 'history_stale': 'Brak oceny predykcyjnej', 'forecast_stale': 'Brak oceny predykcyjnej'} %}
{% set action_labels = {'absorb_pv': 'Zwiększ pochłanianie PV przez magazyn', 'limit_export': 'Ogranicz eksport', 'monitor': 'Monitoruj bez zmiany nastaw', 'hold': 'Wstrzymaj działanie', 'restore': 'Przywróć ustawienie bazowe', 'release_export': 'Stopniowo zwolnij ograniczenie eksportu', 'grid_discharge_preparation': 'Przygotuj miejsce kontrolowanym rozładowaniem', 'preserve_headroom': 'Zachowaj wolne miejsce', 'none': 'Brak działania'} %}
{% set horizon_labels = {
  'today': 'dzisiaj', 'tomorrow': 'jutro', 'none': 'brak',
